import Foundation
import GlowroomCore
import Testing
@testable import Glowroom

/// Tests of the isolated LC-03 reference, not of a production rendering path.
/// Numeric expected values are generated by pinned ORIGINAL Rust functions;
/// see tools/lightcraft-evaluation/lc03-reference-oracle for provenance/license.
@Suite("Lightcraft isolated tone reference")
struct LightcraftToneReferenceTests {
    @Test func filtersMatchFrozenOriginalRustFloat32Vectors() throws {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("tools/lightcraft-evaluation/lc03-reference-oracle/vectors.json")
        let vectors = try JSONDecoder().decode(Oracle.self, from: Data(contentsOf: url))
        #expect(vectors.upstream_commit == "f9b0c8c8a12c8fa17b7afb5baa00f9ee1bbd7b15")
        #expect(vectors.cases.count == 11)
        for item in vectors.cases {
            let input = LightcraftToneFilters.Plane(width: item.width, height: item.height, values: item.input)
            let result: LightcraftToneFilters.Plane
            switch item.operation {
            case "median": result = try LightcraftToneFilters.medianHV(input, radius: item.radius)
            case "gaussian": result = try LightcraftToneFilters.gaussian(input, sigma: item.sigma)
            case "guided": result = try LightcraftToneFilters.guidedFast(input, sigma: item.sigma, epsilon: item.epsilon)
            case "tone_base": result = try LightcraftToneFilters.toneBase(input, sigma: item.sigma, detail: item.radius)
            case "resize_box": result = try LightcraftToneFilters.resize(input, width: item.output_width,
                                                                        height: item.output_height, filter: .box)
            case "resize_bilinear": result = try LightcraftToneFilters.resize(input, width: item.output_width,
                                                                             height: item.output_height, filter: .bilinear)
            default: Issue.record("Unknown oracle operation: \(item.operation)"); continue
            }
            #expect(result.width == item.output_width)
            #expect(result.height == item.output_height)
            #expect(result.values.count == item.output.count)
            let error = zip(result.values, item.output).map { abs($0 - $1) }.max() ?? .infinity
            #expect(error <= vectors.absolute_float_tolerance,
                    "\(item.operation), sigma \(item.sigma), \(item.width)×\(item.height): max error \(error)")
        }
    }

    @Test func medianKeepsTheUpstreamStepAndDropsOnePixelLines() throws {
        let width = 40, height = 30
        let values: [Float] = (0..<(width * height)).map { index in
            let x = index % width, y = index / width
            return (x < 20 ? -2 : 2) + (y == 15 || x == 8 ? -3 : 0)
        }
        let plane = LightcraftToneFilters.Plane(width: width, height: height, values: values)
        #expect(try LightcraftToneFilters.medianHV(plane, radius: 0).values == values)
        let filtered = try LightcraftToneFilters.medianHV(plane, radius: 2)
        for index in values.indices { #expect(filtered.values[index] == (index % width < 20 ? -2 : 2)) }
    }

    @Test func neutralAndExposureOnlyPreserveSignedExtendedRGBAndAlpha() throws {
        let input = try AlgorithmEvaluationRaster(width: 4, height: 1, pixels: [3, 1, -2, 0,
            1.4, -0.25, 0.7, 0.03125, -0.1, 0.6, 1.2, 0.5, 0.2, 0.3, 0.4, 1])
        let adapter = LightcraftToneReference()
        #expect(try adapter.render(input, settings: .neutral).pixels == input.pixels)
        var settings = EditSettings.neutral
        settings.exposure = 1
        let output = try adapter.render(input, settings: settings)
        for offset in stride(from: 0, to: input.pixels.count, by: 4) {
            #expect(output.pixels[offset + 3] == input.pixels[offset + 3])
            for channel in 0..<3 { #expect(abs(output.pixels[offset + channel] - input.pixels[offset + channel] * 2) < 0.000005) }
        }
    }

    @Test func preparedSnapshotMatchesFreshAfterSliderAndExposureChanges() throws {
        let input = try scene(width: 120, height: 60)
        let adapter = LightcraftToneReference(pixelsPerLongEdge: 1200)
        let prepared = try adapter.prepare(input)
        let original = input.sha256
        for value in [-1.0, 0.3, 1.0, -0.7, 0.0] {
            var settings = EditSettings.neutral
            settings.shadows = value * 100
            settings.highlights = -value * 100
            settings.exposure = value * 0.5
            let reused = try adapter.apply(prepared, settings: settings)
            let fresh = try adapter.render(input, settings: settings)
            #expect(reused.pixels == fresh.pixels, "A slider/exposure change must not double-apply exposure or reuse old gains")
        }
        #expect(prepared.input.sha256 == original)
        #expect(input.sha256 == original)
    }

    @Test func processAndGeometryHaveDistinctPreparedBases() throws {
        let input = try scene(width: 120, height: 60)
        let v1 = try LightcraftToneReference(process: .v1, pixelsPerLongEdge: 1200).prepare(input)
        let v2 = try LightcraftToneReference(process: .v2, pixelsPerLongEdge: 1200).prepare(input)
        let preview = try LightcraftToneReference(process: .v2, pixelsPerLongEdge: 300).prepare(input)
        #expect(v1.detailRadius == 0)
        #expect(v2.detailRadius == 2)
        #expect(preview.detailRadius == 0)
        #expect(abs(v2.sigma - 18) < 0.000001)
        #expect(abs(preview.sigma - 4.5) < 0.000001)
        #expect(v1.base != v2.base)
        #expect(preview.base != v2.base)
        for process in [LightcraftToneReference.Process.v1, .v2, .v1, .v2] {
            let next = try LightcraftToneReference(process: process, pixelsPerLongEdge: 1200).prepare(input)
            #expect(next.base == (process == .v1 ? v1.base : v2.base))
        }
    }

    @Test func upstreamFineLinesKeepTheirRegionalContrastUnderV2() throws {
        // This is tests_tone.rs::scene/on_line at its original 1200×600 size.
        // We measure linear isolated output, without Lightcraft's display tone map.
        let input = try scene(width: 1200, height: 600)
        let v1 = LightcraftToneReference(process: .v1), v2 = LightcraftToneReference(process: .v2)
        let prepared1 = try v1.prepare(input), prepared2 = try v2.prepare(input)
        var highlights = EditSettings.neutral, shadows = EditSettings.neutral
        highlights.highlights = -100; shadows.shadows = 100
        let h1 = try v1.apply(prepared1, settings: highlights)
        let h2 = try v2.apply(prepared2, settings: highlights)
        let s2 = try v2.apply(prepared2, settings: shadows)
        let plainBright = lineContrast(input, xRange: 40..<540)
        let plainDark = lineContrast(input, xRange: 640..<1160)
        #expect(lineContrast(h1, xRange: 40..<540) < 0.85 * plainBright)
        #expect(lineContrast(h2, xRange: 40..<540) > 0.9 * plainBright)
        #expect(lineContrast(s2, xRange: 640..<1160) > 0.9 * plainDark)
        #expect(mean(h2, xRange: 40..<540) < 0.8 * mean(input, xRange: 40..<540))
        #expect(mean(s2, xRange: 640..<1160) > 1.2 * mean(input, xRange: 640..<1160))
        #expect(abs(mean(h2, xRange: 700..<1160) - mean(input, xRange: 700..<1160)) < 0.005)
        #expect(abs(mean(s2, xRange: 40..<540) - mean(input, xRange: 40..<540)) < 0.005)
    }

    @Test func strongEdgeDoesNotGainAVisibleLightOrDarkRim() throws {
        let width = 1200, height = 120
        let input = try raster(width: width, height: height) { x, _ in (x < width / 2 ? 0.85 : 0.011, 1) }
        var settings = EditSettings.neutral
        settings.highlights = -100
        let output = try LightcraftToneReference().render(input, settings: settings)
        let at: (AlgorithmEvaluationRaster, Int) -> Float = { $0.pixels[(height / 2 * width + $1) * 4] }
        let farChange = at(output, 100) - at(input, 100)
        for x in (width / 2 - 40)..<(width / 2 + 40) {
            let change = at(output, x) - at(input, x)
            let expected: Float = x < width / 2 ? farChange : 0
            // The existing LC-01 linear halo limit; upstream's RGBA8 ±5-level
            // bound includes a display tone map absent from this experiment.
            #expect(abs(change - expected) <= 0.03, "x=\(x): edge change \(change), regional change \(expected)")
        }
    }

    @Test func transparentNeighboursDoNotDarkenAConstantVisibleRegion() throws {
        let width = 40, height = 24
        let opaque = try raster(width: width, height: height) { _, _ in (0.03, 1) }
        var covered = try raster(width: width, height: height) { x, y in
            (0.03, x >= 20 ? 0 : (x + y).isMultiple(of: 3) ? 0.125 : 0.5)
        }
        // The existing raster's storage is mutable: invisible, finite RGB still
        // cannot contaminate the alpha-weighted local statistics.
        for y in 0..<height { for x in 20..<width {
            let offset = (y * width + x) * 4
            covered.pixels[offset] = 20; covered.pixels[offset + 1] = -5; covered.pixels[offset + 2] = 3
        } }
        var settings = EditSettings.neutral
        settings.shadows = 100
        let adapter = LightcraftToneReference(pixelsPerLongEdge: 1200)
        let expected = try adapter.render(opaque, settings: settings)
        let output = try adapter.render(covered, settings: settings)
        for offset in stride(from: 0, to: output.pixels.count, by: 4) {
            #expect(output.pixels[offset + 3] == covered.pixels[offset + 3])
            for channel in 0..<3 {
                if covered.pixels[offset + 3] > 0 {
                    #expect(abs(output.pixels[offset + channel] - expected.pixels[offset + channel]) < 0.000005)
                } else { #expect(output.pixels[offset + channel] == 0) }
            }
        }
    }

    @Test func nonneutralGainKeepsColorRatiosWithoutClippingSignedComponents() throws {
        let input = try AlgorithmEvaluationRaster(width: 2, height: 1,
            pixels: [1.4, -0.25, 0.7, 0.5, -0.1, 0.6, 1.2, 1])
        var settings = EditSettings.neutral
        settings.highlights = -60; settings.shadows = 40
        let output = try LightcraftToneReference().render(input, settings: settings)
        for offset in stride(from: 0, to: input.pixels.count, by: 4) {
            let gain = output.pixels[offset] / input.pixels[offset]
            #expect(gain > 0)
            for channel in 1..<3 {
                #expect(abs(output.pixels[offset + channel] / input.pixels[offset + channel] - gain) < 0.000005)
            }
            #expect(output.pixels[offset + 3] == input.pixels[offset + 3])
        }
        #expect(output.pixels[1] < 0 && output.pixels[4] < 0)
    }

    @Test func geometryAndUnsupportedSettingsFailExplicitly() throws {
        let input = try raster(width: 1, height: 1) { _, _ in (0.1, 1) }
        for scale in [Double.nan, .infinity, -.infinity, 0, -1, 1_000_001] {
            #expect(throws: LightcraftToneReference.Failure.self) {
                _ = try LightcraftToneReference(pixelsPerLongEdge: scale).prepare(input)
            }
        }
        for native in [0, -1, 1_000_001] {
            #expect(throws: LightcraftToneReference.Failure.self) {
                _ = try LightcraftToneReference(nativeLong: native).prepare(input)
            }
        }
        for invalid in [Double.nan, .infinity, -.infinity] {
            var settings = EditSettings.neutral
            settings.highlights = invalid
            #expect(throws: LightcraftToneReference.Failure.self) {
                _ = try LightcraftToneReference().render(input, settings: settings)
            }
        }
        var unsupported = EditSettings.neutral
        for keyPath in [\EditSettings.clarity, \.naturalBalanceAmount] {
            unsupported = .neutral
            unsupported[keyPath: keyPath] = 1
            #expect(throws: LightcraftToneReference.Failure.self) {
                _ = try LightcraftToneReference().render(input, settings: unsupported)
            }
        }
        let v1 = try LightcraftToneReference(process: .v1).prepare(input)
        #expect(throws: LightcraftToneReference.Failure.self) {
            _ = try LightcraftToneReference(process: .v2).apply(v1, settings: .neutral)
        }
        let uncropped = try LightcraftToneReference(nativeLong: 6000, pixelsPerLongEdge: 400).prepare(input)
        #expect(throws: LightcraftToneReference.Failure.self) {
            _ = try LightcraftToneReference(nativeLong: 6000, pixelsPerLongEdge: 1200).apply(uncropped, settings: .neutral)
        }
        #expect(throws: LightcraftToneReference.Failure.self) {
            _ = try LightcraftToneReference(nativeLong: 4000, pixelsPerLongEdge: 400).apply(uncropped, settings: .neutral)
        }
    }

    @Test func nonfiniteBlurScaleIsBoundedAndGuidedParametersRejectInvalidValues() throws {
        let p = LightcraftToneFilters.Plane(width: 4, height: 3, values: (0..<12).map(Float.init))
        #expect(try LightcraftToneFilters.gaussian(p, sigma: .nan).values == p.values)
        #expect(try LightcraftToneFilters.gaussian(p, sigma: -.infinity).values == p.values)
        let infinite = try LightcraftToneFilters.gaussian(p, sigma: .infinity)
        let capped = try LightcraftToneFilters.gaussian(p, sigma: 8)
        #expect(infinite.values == capped.values)
        #expect(infinite.values.allSatisfy { $0.isFinite })
        for sigma: Float in [.nan, .infinity, -.infinity, -1] {
            #expect(throws: LightcraftToneReference.Failure.self) {
                _ = try LightcraftToneFilters.guidedFast(p, sigma: sigma, epsilon: 0.35)
            }
        }
        for epsilon: Float in [.nan, .infinity, -.infinity, 0, -1] {
            #expect(throws: LightcraftToneReference.Failure.self) {
                _ = try LightcraftToneFilters.guidedFast(p, sigma: 3, epsilon: epsilon)
            }
        }
    }

    @Test func invalidPixelsAreRejectedAfterMutableRasterStorageChanges() throws {
        for invalid: Float in [.nan, .infinity, -.infinity] {
            var input = try AlgorithmEvaluationRaster(width: 1, height: 1, pixels: [0.2, 0.3, 0.4, 1])
            input.pixels[0] = invalid
            #expect(throws: LightcraftToneReference.Failure.self) { _ = try LightcraftToneReference().prepare(input) }
        }
    }

    @Test func onePixelAndSingleAxisInputsRemainFiniteAndKeepAlpha() throws {
        for (width, height) in [(1, 1), (1, 9), (11, 1), (2, 2)] {
            let input = try raster(width: width, height: height) { _, _ in (0.03, 0.125) }
            var settings = EditSettings.neutral
            settings.shadows = 100; settings.highlights = -100
            let output = try LightcraftToneReference().render(input, settings: settings)
            #expect(output.width == width && output.height == height)
            #expect(output.pixels.allSatisfy { $0.isFinite })
            for index in stride(from: 3, to: output.pixels.count, by: 4) { #expect(output.pixels[index] == 0.125) }
            let first = output.pixels[0]
            for index in stride(from: 0, to: output.pixels.count, by: 4) { #expect(abs(output.pixels[index] - first) < 0.000005) }
        }
    }

    @Test func cancellationCannotPublishPreparedOrAppliedResults() async throws {
        let input = try scene(width: 120, height: 60)
        let adapter = LightcraftToneReference()
        let prepared = try adapter.prepare(input)
        let prepareTask = Task {
            withUnsafeCurrentTask { $0?.cancel() }
            return try adapter.prepare(input)
        }
        await #expect(throws: CancellationError.self) { _ = try await prepareTask.value }
        let applyTask = Task {
            withUnsafeCurrentTask { $0?.cancel() }
            var settings = EditSettings.neutral
            settings.shadows = 100
            return try adapter.apply(prepared, settings: settings)
        }
        await #expect(throws: CancellationError.self) { _ = try await applyTask.value }
    }

    @Test func independentlyPreparedImagesRemainDistinctAcrossRapidSelectionChanges() async throws {
        let a = try scene(width: 120, height: 60)
        let b = try raster(width: 96, height: 48) { x, y in
            (Float((x * 7 + y * 11) % 19 + 1) / 30, 1)
        }
        let adapter = LightcraftToneReference(pixelsPerLongEdge: 1200)
        async let preparingA = adapter.prepare(a)
        async let preparingB = adapter.prepare(b)
        let (preparedA, preparedB) = try await (preparingA, preparingB)
        var settings = EditSettings.neutral
        settings.shadows = 60; settings.highlights = -40
        let expectedA = try adapter.render(a, settings: settings)
        let expectedB = try adapter.render(b, settings: settings)
        #expect(expectedA.sha256 != expectedB.sha256)
        for chooseA in [true, false, true, false, false, true] {
            let result = try adapter.apply(chooseA ? preparedA : preparedB, settings: settings)
            #expect(result.sha256 == (chooseA ? expectedA : expectedB).sha256)
        }
        // The reference returns snapshots, not UI updates; callers decide which
        // completed request is current. There is no mutable shared result slot.
        #expect(preparedA.input.sha256 == a.sha256)
        #expect(preparedB.input.sha256 == b.sha256)
    }

    @Test(.timeLimit(.minutes(1))) func cancellationDuringParallelRowsDiscardsThePartialResult() async throws {
        let entered = AsyncStream<Void>.makeStream(bufferingPolicy: .bufferingNewest(1))
        let release = DispatchSemaphore(value: 0)
        let synchronousWorker = TestSynchronousWorker()
        let worker = Task.detached {
            try await synchronousWorker.run {
                try LightcraftToneFilters.rows(width: 1024, height: 128) { row, output in
                    if row == 0 {
                        entered.continuation.yield(())
                        release.wait()
                    }
                    for index in output.indices { output[index] = Float(row) }
                }
            }
        }
        // A buffered checkpoint survives delayed test scheduling. Only the
        // real cancellation below releases the row; no elapsed deadline can
        // accidentally let the operation finish before cancellation is tested.
        // The synchronous native wait runs off the cooperative executor.
        defer {
            worker.cancel(); release.signal(); entered.continuation.finish()
        }
        var iterator = entered.stream.makeAsyncIterator()
        guard await iterator.next() != nil else { throw CancellationError() }
        try Task.checkCancellation()
        worker.cancel()
        release.signal()
        await #expect(throws: CancellationError.self) { _ = try await worker.value }
    }

    private func scene(width: Int, height: Int) throws -> AlgorithmEvaluationRaster {
        try raster(width: width, height: height) { x, y in
            let texture = 1 + 0.06 * (Float((x * 7 + y * 13) % 5) - 2) / 2
            let value: Float = x < width / 2 ? (onLine(x, y) ? 0.14 : 0.85) : (onLine(x, y) ? 0.06 : 0.011)
            return (value * texture, 1)
        }
    }

    private func raster(width: Int, height: Int, value: (Int, Int) -> (Float, Float)) throws -> AlgorithmEvaluationRaster {
        var pixels = [Float](repeating: 0, count: width * height * 4)
        for y in 0..<height { for x in 0..<width {
            let (v, a) = value(x, y), offset = (y * width + x) * 4
            pixels[offset] = v; pixels[offset + 1] = v; pixels[offset + 2] = v; pixels[offset + 3] = a
        } }
        return try .init(width: width, height: height, pixels: pixels)
    }

    private func onLine(_ x: Int, _ y: Int) -> Bool { (x / 48 + y / 48).isMultiple(of: 2) && (x % 4 == 1 || y % 5 == 2) }

    private func lineContrast(_ image: AlgorithmEvaluationRaster, xRange: Range<Int>) -> Double {
        var on = 0.0, off = 0.0, onCount = 0, offCount = 0
        for y in 40..<(image.height - 40) { for x in xRange {
            let value = Double(image.pixels[(y * image.width + x) * 4])
            if onLine(x, y) { on += value; onCount += 1 } else { off += value; offCount += 1 }
        } }
        return abs(log2((off / Double(offCount)) / (on / Double(onCount))))
    }

    private func mean(_ image: AlgorithmEvaluationRaster, xRange: Range<Int>) -> Double {
        var sum = 0.0, count = 0
        for y in 40..<(image.height - 40) { for x in xRange {
            sum += Double(image.pixels[(y * image.width + x) * 4]); count += 1
        } }
        return sum / Double(count)
    }

    private struct Oracle: Decodable {
        let upstream_commit: String
        let absolute_float_tolerance: Float
        let cases: [Case]
        struct Case: Decodable {
            let operation: String
            let width: Int, height: Int, output_width: Int, output_height: Int, radius: Int
            let sigma: Float, epsilon: Float
            let input: [Float], output: [Float]
        }
    }
}
